def scope_schedules_to_account(apps, schema_editor):
    """Point each existing per-user Jellyfin schedule at that user's one account.

    Schedules used to carry only ``user_id``; with several connections per user
    each must address its own account, so the existing one gets its account id.
    """
    JellyfinAccount = apps.get_model("integrations", "JellyfinAccount")
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")

    for task in PeriodicTask.objects.filter(task__in=JELLYFIN_TASK_NAMES):
        try:
            kwargs = json.loads(task.kwargs or "{}")
        except ValueError:
            continue
        if kwargs.get("account_id") or "user_id" not in kwargs:
            continue
        account = JellyfinAccount.objects.filter(user_id=kwargs["user_id"]).first()
        if account is None:
            continue
        kwargs["account_id"] = account.id
        task.kwargs = json.dumps(kwargs)
        task.save(update_fields=["kwargs"])


